"""Generate supabase/seed.sql from config/airports/*.json so there is one source of truth."""

from __future__ import annotations

import json

from .config import Airport
from .detection.pipeline import ALGORITHM_VERSION, DEFAULT_THRESHOLDS


def q(s) -> str:
    return "null" if s is None else "'" + str(s).replace("'", "''") + "'"


def ring_wkt(ring) -> str:
    return "POLYGON((" + ", ".join(f"{lon} {lat}" for lon, lat in ring) + "))"


def seed_sql(ap: Airport) -> str:
    raw = ap.raw
    out = [
        "-- Generated by `python -m airwatch seed-sql`. Edit config/airports/*.json, not this file.",
        "-- Seeds KEIK, its approximate runway, placeholder zones, the synthetic source and policy defaults.",
        "begin;",
        f"""insert into airwatch.airports (id, icao, name, timezone, reference, elevation_ft, pattern_altitude_ft, pattern_verified, config, active)
values ({q(ap.id)}, {q(ap.icao)}, {q(ap.name)}, {q(ap.timezone)}, st_setsrid(st_makepoint({ap.lon}, {ap.lat}), 4326),
        {ap.elevation_ft}, {ap.pattern_altitude_ft}, {str(raw['pattern'].get('verified', False)).lower()}, {q(json.dumps(raw['pattern']))}::jsonb, {str(ap.active).lower()})
on conflict (icao) do nothing;""",
    ]
    for r in raw["runways"]:
        a, b = r["ends"]
        out.append(f"""insert into airwatch.runways (airport_id, ident, length_ft, width_ft, centerline, ends, source, version)
values ({q(ap.id)}, {q(r['id'])}, {r['length_ft']}, {r.get('width_ft') or 'null'},
        st_setsrid(st_makeline(st_makepoint({a['lon']}, {a['lat']}), st_makepoint({b['lon']}, {b['lat']})), 4326),
        {q(json.dumps(r['ends']))}::jsonb, {q(r['source'])}, {q(r['version'])})
on conflict (airport_id, ident, version) do nothing;""")
    for z in ap.zones:
        out.append(f"""insert into airwatch.zones (id, airport_id, slug, label, geom, synthetic)
values ({q(z.id)}, {q(ap.id)}, {q(z.slug)}, {q(z.label)}, st_geomfromtext({q(ring_wkt(z.ring))}, 4326), {str(z.synthetic).lower()})
on conflict (airport_id, slug) do nothing;""")
    out += [
        """insert into airwatch.sources (name, provider, license_ref, allows_public_display, allows_raw_retention,
  allows_aircraft_id_display, freshness_expectation_s, active, notes)
values ('synthetic', 'internal', 'internal-synthetic', true, true, false, 60, true,
        'Generated test data. Replace with a licensed source only after docs/license-checklist.md is complete.')
on conflict (name) do nothing;""",
        f"""insert into airwatch.settings (airport_id, publication_mode, min_public_confidence)
values ({q(ap.id)}, 'reviewed_only', 0.5) on conflict do nothing;""",
        f"""insert into airwatch.methodology_versions (version, thresholds, changelog)
values ({q(ALGORITHM_VERSION)}, {q(json.dumps(DEFAULT_THRESHOLDS.to_dict()))}::jsonb,
        'Initial definitions for overflights, candidate circuits and likely touch-and-go events.')
on conflict do nothing;""",
        "commit;",
        "",
    ]
    return "\n\n".join(out)
